// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public {
        address[] memory proposers = new address[](1);
        proposers[0] = address(this);
        address[] memory executors = new address[](1);
        executors[0] = address(this);
        c = new TimelockController(0, proposers, executors);
    }
    function testFuzz_property(bytes32 role) public {
        bytes32 expectedAdmin;
        if (role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE()) {
            expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        } else if (role == c.TIMELOCK_ADMIN_ROLE()) {
            expectedAdmin = c.TIMELOCK_ADMIN_ROLE();
        } else if (role == c.DEFAULT_ADMIN_ROLE()) {
            expectedAdmin = c.DEFAULT_ADMIN_ROLE();
        } else {
            expectedAdmin = bytes32(0);
        }
        assertTrue(c.getRoleAdmin(role) == expectedAdmin);
    }
}
